15	MAX_BODY_BYTES = 10 * 1024 * 1024
16	QUESTION_TYPES = ("text", "single_choice")
17	
18	PAGE = r"""<!doctype html>
19	<html lang="zh-CN">
20	<meta charset="utf-8">
21	<meta name="viewport" content="width=device-width,initial-scale=1">
22	<title>OpenSurvey · 问卷调查与反馈管理</title>
23	<style>
24	:root{--blue:#175b9c;--red:#c0392b;--grey:#666;--line:#d8dce3}
25	*{box-sizing:border-box}
26	body{font-family:system-ui,"PingFang SC","Microsoft YaHei",sans-serif;max-width:52rem;margin:2.5rem auto;padding:0 1rem;line-height:1.7;color:#1f2430}
27	a{color:var(--blue)}
28	h1{margin-bottom:.2rem}
29	h2{margin-top:2.2rem;border-bottom:1px solid var(--line);padding-bottom:.3rem}
30	.muted{color:var(--grey);font-size:.92rem}
31	ul.plain{list-style:none;padding-left:0}
32	ul.plain li{padding:.25rem 0;border-bottom:1px dashed var(--line)}
33	form label{display:block;margin:1rem 0 .25rem;font-weight:600}
34	input[type=text],textarea{width:100%;padding:.5rem .6rem;border:1px solid var(--line);border-radius:.35rem;font:inherit}
35	textarea{resize:vertical}
36	/* 标题与选项允许内部换行：用随内容增高的 textarea 展示，不能压成单行输入框 */
37	textarea.grow{resize:none;overflow:hidden;min-height:2.4rem;line-height:1.5}
38	.card{border:1px solid var(--line);border-radius:.5rem;padding:1rem 1.2rem;margin:1rem 0;background:#fafbfd}
39	.q-head{display:flex;align-items:center;gap:.7rem;flex-wrap:wrap;margin-bottom:.5rem}
40	.q-index{font-weight:700}
41	.tag{font-size:.8rem;background:#e8f0fa;color:var(--blue);border-radius:1rem;padding:.05rem .6rem}
42	.tag.required{background:#fdecea;color:var(--red)}
43	.req{margin:0;font-weight:400;display:flex;align-items:center;gap:.3rem}
44	.spacer{flex:1}
45	button{font:inherit;cursor:pointer}
46	.btn{border:1px solid var(--blue);background:var(--blue);color:#fff;border-radius:.35rem;padding:.45rem 1.1rem;text-decoration:none;display:inline-block}
47	.btn.secondary{background:#fff;color:var(--blue)}
48	.link{border:none;background:none;color:var(--blue);padding:0;font-size:.92rem}
49	.link.danger{color:var(--red)}
50	.row-actions{display:flex;gap:.8rem;flex-wrap:wrap;margin-top:1.2rem}
51	.opt-row{display:flex;align-items:center;gap:.6rem;margin:.4rem 0}
52	.opt-index{color:var(--grey);font-size:.9rem;min-width:3.2rem}
53	.banner{border:1px solid var(--red);background:#fdf3f2;color:var(--red);border-radius:.5rem;padding:.7rem 1rem;margin:1rem 0;white-space:normal}
54	.banner ul{margin:.4rem 0 0;padding-left:1.2rem}
55	.banner button{color:var(--red);text-decoration:underline;background:none;border:none;padding:0;text-align:left}
56	/* 保存状态条：与错误提示条区分开，明确“刚才那次提交已保存”与“还有未保存修改” */
57	.save-status{margin:1rem 0;display:flex;flex-direction:column;gap:.5rem}
58	.save-status[hidden]{display:none}
59	.save-note{border-radius:.5rem;padding:.7rem 1rem;white-space:normal}
60	.save-note.saved{border:1px solid #1e7e45;background:#ecf7f0;color:#155c33}
61	.save-note.dirty{border:1px solid #9a6d12;background:#fdf6e3;color:#7a5207}
62	/* 等待保存结果：蓝色中性提示，与成功（绿）、未保存（黄）、错误（红）区分 */
63	.save-note.saving{border:1px solid var(--blue);background:#eef4fb;color:#144a80}
64	button:disabled{opacity:.55;cursor:not-allowed}
65	.field-err{color:var(--red);font-size:.85rem;margin:.25rem 0 0;min-height:1px}
66	.invalid{border-color:var(--red)!important;background:#fdf6f5}
67	.detail-meta{color:var(--grey);font-size:.9rem}
68	.detail-desc,.opt-text-display{white-space:pre-wrap}
69	/* 标题中被接口保留的内部换行在列表与详情中也要原样显示 */
70	h2,.q-list .q-line,ul.plain a{white-space:pre-wrap}
71	.q-list>li{margin:1rem 0}
72	.q-list .q-line{font-weight:600}
73	.q-list ol{margin:.4rem 0 0 1.4rem}
74	</style>
75	<main>
76	<h1>OpenSurvey</h1>
77	<p>问卷调查与反馈管理</p>
78	<div id="app"></div>
79	<p class="muted"><a href="/api/surveys">问卷列表接口</a> · <a href="/health">服务状态</a></p>
80	</main>
81	<script>
82	"use strict";
83	const app = document.getElementById("app");
84	
85	// 每次进入一个页面都开启新一代视图：切换首页/详情/编辑、重新进入同一份问卷、
86	// 重试加载以及浏览器前进/后退都会使代数递增。较早一代页面发起的请求再晚
87	// 返回也必须丢弃，不能覆盖用户当前所在页面。
88	let activeView = 0;
89	
90	// 首尾裁剪必须与接口（Python str.strip()）逐字符一致，网页校验、提交内容与
91	// “是否还有未保存修改”的比较才能表达同一份文本含义。JS 原生 trim() 的字符集
92	// 恰好不同：它会裁掉 U+FEFF（接口保留该字符），却不裁 U+0085 与 U+001C–
93	// U+001F（接口会把它们当空白裁掉）。这里显式列出接口会裁的 29 个字符，
94	// U+FEFF 刻意不在其中；内部字符（含内部换行）一律不动。说明字段从不裁剪。
95	const API_TRIM_CLASS =
96	  "\\t\\n\\v\\f\\r\\x1c-\\x1f\\x20\\u0085\\u00a0\\u1680" +
97	  "\\u2000-\\u200a\\u2028\\u2029\\u202f\\u205f\\u3000";
98	const apiTrimRe = new RegExp(
99	  "^[" + API_TRIM_CLASS + "]+|[" + API_TRIM_CLASS + "]+$", "g");
100	function apiTrim(value) { return value.replace(apiTrimRe, ""); }
101	
102	// 换行归一化：接口会原样保留文本内部的回车换行（CRLF，\r\n）、单独回车
103	// （CR，\r）与换行（LF，\n），但这些值赋给 textarea 后会被浏览器立即统一
104	// 成 LF（实测在赋值给 .value 的那一刻即发生）。因此编辑页必须在把原稿送进
105	// 输入框之前记录原始字符串，保存时再按“可见内容是否改变”决定还原原稿还是
106	// 采用当前输入；比较一律基于归一化为 LF 的文本，使三种换行在编辑框里的同
107	// 一份可见内容被视为“没有改变”。
108	function normalizeNL(value) { return value.replace(/\r\n|\r|\n/g, "\n"); }
109	
110	// 仅编辑模式使用：输入框元素 -> 打开编辑页时该字段从接口读到的原始字符串。
111	// 用 WeakMap 是为了让随题目/选项删除而移除的元素连同记录一起被回收，绝不
112	// 需要手工清理，也不会把已删除行的原文错配到后来顶上来的另一行。新建模式
113	// 下不写入任何记录。
114	const origMap = new WeakMap();
115	function rememberOriginal(el, raw) { origMap.set(el, String(raw)); }
116	
117	// 计算一个文本字段“实际要保存”的字符串：
118	// - 编辑模式且该字段可见内容与打开时一致：还原为原稿，保留原始 CRLF/CR/LF；
119	// - 其余情况（真正修改过，或新建模式）：采用输入框当前文本（浏览器统一为 LF）。
120	// 比较规则与“判断文字是否改变”的既有规则一致：trimFields 为真时（问卷标题、
121	// 题目标题、选项）首尾空白不参与比较，因此只增删首尾空白也算未改变、仍还原
122	// 原稿（原稿内部的 CRLF/CR 不会因此被 LF 覆盖）；说明字段不裁剪，逐字符比较。
123	function resolveFieldValue(el, {trimFields = false} = {}) {
124	  const current = el.value;
125	  const original = origMap.get(el);
126	  if (original !== undefined) {
127	    const a = trimFields ? apiTrim(normalizeNL(current)) : normalizeNL(current);
128	    const b = trimFields ? apiTrim(normalizeNL(original)) : normalizeNL(original);
129	    if (a === b) return original;
130	  }
131	  return current;
132	}
133	
134	function h(tag, attrs, ...children) {
135	  const el = document.createElement(tag);
136	  if (attrs) for (const [k, v] of Object.entries(attrs)) {
137	    if (v === null || v === undefined) continue;
138	    if (k === "class") el.className = v;
139	    else if (k.startsWith("on")) el.addEventListener(k.slice(2), v);
140	    else el.setAttribute(k, v);
141	  }
142	  for (const child of children.flat()) {
143	    if (child === null || child === undefined) continue;
144	    el.append(child.nodeType ? child : document.createTextNode(String(child)));
145	  }
146	  return el;
147	}
148	
149	/* ---------- 问卷表单（新建 / 编辑共用） ---------- */
150	
151	function buildSurveyForm(existing, hooks, view) {
152	  const mode = existing ? "edit" : "create";
153	
154	  const banner = h("div", {class: "banner", id: "form-banner"});
155	  banner.hidden = true;
156	
157	  // 编辑模式下保存结果的状态条：成功保存与“仍有未保存修改”必须分开展示，
158	  // 不能只给一条笼统的“保存成功”。新建模式不使用它（保存成功即进入详情）。
159	  const statusBar = h("div", {class: "save-status", id: "save-status", role: "status"});
160	  statusBar.hidden = true;
161	
162	  const titleInput = h("textarea", {id: "survey-title", rows: "1", class: "grow",
163	    maxlength: "200", placeholder: "请输入问卷标题（可含换行）"});
164	  const titleErr = h("p", {class: "field-err", id: "title-err"});
165	  const descArea = h("textarea", {id: "survey-desc", rows: "4", placeholder: "问卷说明（可留空，支持中文、引号与换行）"});
166	  const qBox = h("div", {id: "questions"});
167	  const qErr = h("p", {class: "field-err", id: "questions-err"});
168	
169	  function renumber() {
170	    const cards = qBox.querySelectorAll(".q-card");
171	    cards.forEach((card, i) => {
172	      card.querySelector(".q-index").textContent = `第 ${i + 1} 题`;
173	      card.querySelectorAll(".opt-row").forEach((row, j) => {
174	        row.querySelector(".opt-index").textContent = `选项 ${j + 1}`;
175	      });
176	    });
177	  }
178	
179	  // textarea 的高度随内容变化：单行内容外观与原输入框一致，出现内部换行时
180	  // 自动增高，让换行真实可见、可编辑，而不是被折叠或截断。
181	  function autoGrow(el) {
182	    el.style.height = "auto";
183	    el.style.height = `${el.scrollHeight}px`;
184	  }
185	  // 预填值时元素可能还没挂到文档上（scrollHeight 为 0），延到下一帧布局后再量。
186	  function scheduleGrow(el) { requestAnimationFrame(() => autoGrow(el)); }
187	
188	  function optionRow(value) {
189	    const text = h("textarea", {rows: "1", class: "opt-text grow", placeholder: "选项内容（可含换行）"});
190	    text.addEventListener("input", () => autoGrow(text));
191	    if (value !== undefined && value !== null) {
192	      // 必须在写入 .value 之前记录原稿：赋值一旦发生，CRLF/CR 就已被浏览器
193	      // 归一化成 LF，之后再读 text.value 也拿不回原始换行形式。
194	      if (mode === "edit") rememberOriginal(text, value);
195	      text.value = value; scheduleGrow(text);
196	    }
197	    const row = h("div", {class: "opt-row"},
198	      h("span", {class: "opt-index"}, "选项"),
199	      text,
200	      h("button", {type: "button", class: "link danger", onclick: () => { row.remove(); renumber(); }}, "删除")
201	    );
202	    return row;
203	  }
204	
205	  function addQuestion(type, prefill) {
206	    const isChoice = type === "single_choice";
207	    const options = h("div", {class: "options"});
208	    const card = h("div", {class: "card q-card", "data-type": type},
209	      h("div", {class: "q-head"},
210	        h("span", {class: "q-index"}, "第 N 题"),
211	        h("span", {class: "tag q-type-tag"}, isChoice ? "单选题" : "文本题"),
212	        h("label", {class: "req"},
213	          h("input", {type: "checkbox", class: "q-required"}), "必填（默认非必填）"),
214	        h("span", {class: "spacer"}),
215	        h("button", {type: "button", class: "link danger", onclick: () => { card.remove(); renumber(); }}, "删除本题")
216	      ),
217	      h("textarea", {rows: "1", class: "q-title grow", placeholder: "题目标题（可含换行）"}),
218	      h("p", {class: "field-err q-title-err"})
219	    );
220	    if (isChoice) {
221	      const saved = prefill && Array.isArray(prefill.options) ? prefill.options : null;
222	      if (saved && saved.length) saved.forEach(value => options.append(optionRow(value)));
223	      else options.append(optionRow(), optionRow());
224	      card.append(
225	        options,
226	        h("p", {class: "field-err opt-err"}),
227	        h("button", {type: "button", class: "link add-opt"}, "添加选项")
228	      );
229	      card.querySelector(".add-opt").addEventListener("click", () => {
230	        options.append(optionRow());
231	        renumber();
232	        options.querySelector(".opt-row:last-child .opt-text").focus();
233	      });
234	    }
235	    const qTitleEl = card.querySelector(".q-title");
236	    qTitleEl.addEventListener("input", () => autoGrow(qTitleEl));
237	    if (prefill) {
238	      // 与选项同理：在 .value 赋值（会把 CRLF/CR 归一化成 LF）之前先记住原稿。
239	      if (mode === "edit" && prefill.title != null) rememberOriginal(qTitleEl, prefill.title);
240	      qTitleEl.value = prefill.title != null ? prefill.title : "";
241	      card.querySelector(".q-required").checked = !!prefill.required;
242	    }
243	    scheduleGrow(qTitleEl);
244	    qBox.append(card);
245	    renumber();
246	    if (!prefill) qTitleEl.focus();
247	    return card;
248	  }
249	
250	  function clearErrors() {
251	    banner.hidden = true;
252	    banner.replaceChildren();
253	    titleErr.textContent = "";
254	    qErr.textContent = "";
255	    qBox.querySelectorAll(".invalid").forEach(el => el.classList.remove("invalid"));
256	    qBox.querySelectorAll(".field-err").forEach(el => { el.textContent = ""; });
257	  }
258	
259	  function hideSaveStatus() {
260	    statusBar.hidden = true;
261	    statusBar.replaceChildren();
262	  }
263	
264	  // 保存成功后：绿色块只陈述“刚才提交的内容已保存”；若等待期间又有修改，
265	  // 再追加一块黄色“当前还有未保存的修改”。两者同时出现、含义互不混淆。
266	  function renderSaveStatus(dirty) {
267	    statusBar.replaceChildren(
268	      h("div", {class: "save-note saved", id: "save-note-saved"},
269	        h("strong", null, "已保存：刚才提交的内容已保存到服务器。")),
270	      dirty
271	        ? h("div", {class: "save-note dirty", id: "save-note-dirty"},
272	            h("strong", null,
273	              "当前还有未保存的修改：页面内容在点击保存后又被改动（等待结果期间的修改不会自动补交）。可继续编辑，并再次点击“保存修改”。"))
274	        : null
275	    );
276	    statusBar.hidden = false;
277	  }
278	
279	  // 一次保存进行中：保存按钮禁用并明确显示“正在保存…”，状态条显示等待提示。
280	  // 在请求有明确结果前，重复点击按钮或用键盘再次提交都不会追加请求，也不会
281	  // 清掉等待提示。等待期间标题、说明、题目、选项、必填与增删操作全部可用。
282	  let saving = false;
283	  function setSavingUI() {
284	    submitButton.disabled = true;
285	    submitButton.textContent = "正在保存…";
286	    statusBar.replaceChildren(
287	      h("div", {class: "save-note saving", id: "save-note-saving", role: "status"},
288	        h("strong", null, "正在保存：正在等待本次保存的结果，请稍候。等待期间仍可继续编辑，这些改动不会自动追加到本次提交。"))
289	    );
290	    statusBar.hidden = false;
291	  }
292	  function resetSaveButton() {
293	    submitButton.disabled = false;
294	    submitButton.textContent = submitButton.getAttribute("data-label");
295	  }
296	
297	  // 整份草稿的唯一整理入口：保存时提交的内容、保存前的校验、编辑页判断
298	  // “等待保存期间是否又有修改”都从这里取数，规则只维护这一份。标题/题目
299	  // 标题/选项只按接口规则（apiTrim，与 Python strip 一致）去掉首尾空白，
300	  // 说明与内部换行原样保留；题目与选项按页面当前顺序记录，必填勾选原样。
301	  // 编辑模式下未改动的字段（含“改过又恢复”）由 resolveFieldValue 还原为
302	  // 打开时从接口读到的原稿，使内部 CRLF/CR/LF 不被浏览器的换行归一化改写；
303	  // 真正改动的字段与新建模式一律采用当前输入（浏览器中只会是 LF）。
304	  // 每次调用都返回新建的独立对象（后续输入不会改变已返回的快照），可直接
305	  // 做整体相等比较：改过又恢复原值时结构相同，不会被当成有未保存修改。
306	  function readDraft() {
307	    return {
308	      title: apiTrim(resolveFieldValue(titleInput, {trimFields: true})),
309	      description: resolveFieldValue(descArea),
310	      questions: [...qBox.querySelectorAll(".q-card")].map(card => ({
311	        type: card.dataset.type,
312	        title: apiTrim(resolveFieldValue(card.querySelector(".q-title"), {trimFields: true})),
313	        required: card.querySelector(".q-required").checked,
314	        options: [...card.querySelectorAll(".opt-text")]
315	          .map(el => apiTrim(resolveFieldValue(el, {trimFields: true})))
316	      }))
317	    };
318	  }
319	
320	  function sameState(a, b) { return JSON.stringify(a) === JSON.stringify(b); }
321	
322	  function showBanner(items) {
323	    banner.replaceChildren(h("strong", null, "问卷未能保存，请修改后重试："), h("ul", null,
324	      items.map(it => h("li", null, h("button", {type: "button", onclick: () => it.el && it.el.focus()}, it.msg)))));
325	    banner.hidden = false;
326	    banner.scrollIntoView({behavior: "smooth", block: "nearest"});
327	  }
328	
329	  const actionButtons = [
330	    h("button", {type: "button", class: "btn secondary", onclick: () => addQuestion("text")}, "添加文本题"),
331	    h("button", {type: "button", class: "btn secondary", onclick: () => addQuestion("single_choice")}, "添加单选题"),
332	    h("span", {class: "spacer"})
333	  ];
334	  if (mode === "edit") {
335	    // 离开编辑页即丢弃全部未保存的增删与输入
336	    actionButtons.push(h("a", {class: "btn secondary", href: `#/surveys/${existing.id}`}, "取消"));
337	  }
338	  const submitLabel = mode === "edit" ? "保存修改" : "保存整份问卷";
339	  const submitButton = h("button", {type: "submit", class: "btn", "data-label": submitLabel}, submitLabel);
340	  actionButtons.push(submitButton);
341	
342	  const form = h("form", {id: "draft-form", onsubmit: submitForm},
343	    banner,
344	    statusBar,
345	    h("section", null,
346	      h("h2", null, mode === "edit" ? `编辑问卷草稿 #${existing.id}` : "新建问卷草稿"),
347	      mode === "edit"
348	        ? h("p", {class: "muted"}, "保存将整份替换当前草稿；取消则放弃本次修改，问卷编号和地址不变。")
349	        : null,
350	      h("label", {for: "survey-title"}, "标题"),
351	      titleInput, titleErr,
352	      h("label", {for: "survey-desc"}, "说明"),
353	      descArea,
354	      h("label", null, "题目（按下方顺序保存，至少保留一道题）"),
355	      qBox, qErr,
356	      h("div", {class: "row-actions"}, actionButtons)
357	    )
358	  );
359	
360	  titleInput.addEventListener("input", () => autoGrow(titleInput));
361	  if (mode === "edit") {
362	    // 同样在赋值（会归一化换行）之前记下原稿；说明字段不裁剪、逐字符比较。
363	    rememberOriginal(titleInput, existing.title != null ? existing.title : "");
364	    rememberOriginal(descArea, existing.description || "");
365	    titleInput.value = existing.title != null ? existing.title : "";
366	    descArea.value = existing.description || "";
367	    existing.questions.forEach(question => addQuestion(question.type, question));
368	    renumber();
369	    scheduleGrow(titleInput);
370	
371	    // 最近一次服务器确认保存的表单内容（点击保存时的快照）。它只用于成功返回
372	    // 后判断当前表单相对那次提交有没有新改动；等待期间的输入始终留在表单里，
373	    // 不会被它覆盖，也不会被自动补交。
374	    let savedState = readDraft();
375	
376	    function refreshDirty() {
377	      const dirtyNote = statusBar.querySelector("#save-note-dirty");
378	      // 尚未成功保存过（状态条隐藏）时无需提示。
379	      if (statusBar.hidden || !dirtyNote) return;
380	      // 与点击保存时的整份内容比较：改过又恢复原值即视为无未保存修改。
381	      dirtyNote.hidden = sameState(readDraft(), savedState);
382	    }
383	
384	    // 监听编辑页上全部真实编辑动作（标题/说明/题目标题/选项输入、必填勾选、
385	    // 题目与选项增删）。题目卡片是动态增删的，因此在表单上做事件委托。
386	    form.addEventListener("input", refreshDirty);
387	    form.addEventListener("change", event => {
388	      if (event.target.closest && event.target.closest(".q-required")) refreshDirty();
389	    });
390	    form.addEventListener("click", event => {
391	      const actionable = event.target.closest
392	        && event.target.closest("button.add-opt, button.link.danger, button.btn.secondary");
393	      if (actionable) {
394	        // 新增/删除在本次点击处理中完成，延到冒泡后再读取最终 DOM。
395	        queueMicrotask(refreshDirty);
396	      }
397	    });
398	
399	    hooks = hooks || {};
400	    hooks.markSaved = state => { savedState = state; };
401	    hooks.isCurrent = state => sameState(readDraft(), state);
402	  }
