404	  async function submitForm(event) {
405	    event.preventDefault();
406	    // 已有一次保存尚未得到明确结果：忽略后续点击/键盘提交，不追加请求，也不
407	    // 清除正在显示的等待状态。本次保存只代表首次点击时的那份表单快照。
408	    if (saving) return;
409	    clearErrors();
410	    hideSaveStatus();
411	    const problems = [];
412	
413	    // 点击保存这一刻的整份草稿：整理规则只有 readDraft 一处，校验、提交内容
414	    // 与成功后的“是否有新修改”比较表达的都是同一份草稿。
415	    const draft = readDraft();
416	
417	    if (!draft.title) {
418	      titleInput.classList.add("invalid");
419	      titleErr.textContent = "标题不能为空。";
420	      problems.push({el: titleInput, msg: "问卷标题不能为空。"});
421	    }
422	
423	    const cards = [...qBox.querySelectorAll(".q-card")];
424	    if (cards.length === 0) {
425	      qErr.textContent = "问卷至少需要保留一道题。";
426	      problems.push({el: qBox, msg: "问卷至少需要保留一道题，请先添加题目。"});
427	    }
428	
429	    // 校验针对整理后的草稿内容（空标题、空选项、同题重复选项都按裁剪后的值
430	    // 判断），错误标记仍落在对应的页面输入框上；输入框原文保持不动。
431	    cards.forEach((card, i) => {
432	      const loc = `第 ${i + 1} 题`;
433	      const question = draft.questions[i];
434	      const titleEl = card.querySelector(".q-title");
435	      if (!question.title) {
436	        titleEl.classList.add("invalid");
437	        card.querySelector(".q-title-err").textContent = `${loc}：题目标题不能为空。`;
438	        problems.push({el: titleEl, msg: `${loc}：题目标题不能为空。`});
439	      }
440	      if (question.type === "single_choice") {
441	        const optInputs = [...card.querySelectorAll(".opt-text")];
442	        const optErr = card.querySelector(".opt-err");
443	        const seen = new Set();
444	        question.options.forEach((val, j) => {
445	          if (!val) {
446	            optInputs[j].classList.add("invalid");
447	            optErr.textContent = `${loc}：第 ${j + 1} 个选项不能为空。`;
448	            problems.push({el: optInputs[j], msg: `${loc}：第 ${j + 1} 个选项不能为空。`});
449	          } else if (seen.has(val)) {
450	            optInputs[j].classList.add("invalid");
451	            optErr.textContent = `${loc}：选项“${val}”与同题其他选项重复。`;
452	            problems.push({el: optInputs[j], msg: `${loc}：选项“${val}”重复。`});
453	          }
454	          seen.add(val);
455	        });
456	        if (question.options.length < 2) {
457	          optErr.textContent = `${loc}：单选题至少需要两个选项。`;
458	          problems.push({el: card.querySelector(".add-opt"), msg: `${loc}：单选题至少需要两个选项。`});
459	        }
460	      }
461	    });
462	
463	    if (problems.length) {
464	      showBanner(problems);
465	      return;
466	    }
467	    // 校验通过、请求即将发出：此后到拿到明确结果前只能有这一次保存进行中。
468	    // 纯客户端校验拒绝不会走到这里，因此不会留下等待状态。
469	    saving = true;
470	    setSavingUI();
471	
472	    // 提交内容就是这份草稿本身：文本题不带 options（接口接受省略或空数组），
473	    // 单选题按整理后的选项内容与顺序提交。
474	    const payload = {
475	      title: draft.title,
476	      description: draft.description,
477	      questions: draft.questions.map(q => q.type === "single_choice"
478	        ? {type: q.type, title: q.title, required: q.required, options: q.options}
479	        : {type: q.type, title: q.title, required: q.required})
480	    };
481	    // 点击保存这一刻的整份表单快照：这次请求只代表这份内容。readDraft 返回的
482	    // 是独立对象，等待期间的后续输入不会改变它；成功返回后拿它与重新读取的
483	    // 当前表单比较——等待期间的任何输入/增删都不属于本次保存。
484	    const submittedState = draft;
485	    const endpoint = mode === "edit" ? `/api/surveys/${existing.id}` : "/api/surveys";
486	    // 这次保存只属于发起它的那一代表单；响应再晚返回，只要用户已经离开
487	    // （首页/详情/编辑切换、重新进入同一问卷、浏览器前进后退），其成功或
488	    // 失败结果都必须静默丢弃，不能跳转、清空或提示到当前页面上。
489	    const submitView = view;
490	    let resp;
491	    try {
492	      resp = await fetch(endpoint, {
493	        method: mode === "edit" ? "PUT" : "POST",
494	        headers: {"Content-Type": "application/json"},
495	        body: JSON.stringify(payload)
496	      });
497	    } catch (err) {
498	      if (submitView !== activeView) return;
499	      // 请求未成功：结束等待，保留当前全部输入与增删结果，允许修改后再次保存。
500	      saving = false;
501	      resetSaveButton();
502	      hideSaveStatus();
503	      showBanner([{el: null, msg: `网络错误，问卷尚未保存：${err}`}]);
504	      return;
505	    }
506	    if (submitView !== activeView) return;
507	    let data = {};
508	    try { data = await resp.json(); } catch (_) { /* 保留已输入内容 */ }
509	    if (submitView !== activeView) return;
510	    const saved = mode === "edit" ? resp.status === 200 : resp.status === 201;
511	    if (saved && data.id !== undefined) {
512	      if (mode === "create") {
513	        form.reset();
514	        qBox.replaceChildren();
515	        autoGrow(titleInput);
516	        if (hooks && hooks.onCreated) hooks.onCreated();
517	        location.hash = `#/surveys/${data.id}`;
518	        return;
519	      }
520	      // 编辑模式：先把“这次提交的内容”记为已保存（服务器上的草稿正是它）。
521	      if (hooks && hooks.markSaved) hooks.markSaved(submittedState);
522	      // 比较点击保存前后的整份表单：等待期间改过又恢复原值时结构相同，按
523	      // 无新改动处理，仍进入详情。
524	      const stillSame = hooks && hooks.isCurrent ? hooks.isCurrent(submittedState) : true;
525	      if (stillSame) {
526	        location.hash = `#/surveys/${data.id}`;
527	        return;
528	      }
529	      // 等待期间出现了新的修改：留在编辑页，保留当前完整内容与顺序。绿色块
530	      // 只确认“刚才提交的内容已保存”，黄色块提示“当前还有未保存的修改”，
531	      // 不自动补交，也不撤销已成功的保存。保存恢复可用，再次点击提交的才是
532	      // 当前内容，而不是沿用上一笔提交的旧内容。
533	      saving = false;
534	      resetSaveButton();
535	      renderSaveStatus(true);
536	      return;
537	    }
538	    // 服务端未确认保存成功：结束等待，不清空任何输入，展示具体问题；用户修改
539	    // 后可再次保存（不会自行重发，也不会一直停在“正在保存”）。
540	    saving = false;
541	    resetSaveButton();
542	    hideSaveStatus();
543	    showBanner([{el: null, msg: data.error || `保存失败（HTTP ${resp.status}），问卷未保存，请检查后重试。`}]);
544	  }
545	
546	  return form;
547	}
