719	def validate_survey(obj):
720	    """Validate a decoded survey payload.
721	
722	    Returns (clean_survey, None) on success or (None, error_message) on failure.
723	    Strings are stored trimmed of surrounding whitespace; description keeps its
724	    raw value so Chinese, quotes and newlines are preserved.
725	    """
726	    if not isinstance(obj, dict):
727	        return None, "请求体必须是 JSON 对象"
728	    if "title" not in obj:
729	        return None, "缺少字段 title"
730	    title = obj["title"]
731	    if not isinstance(title, str):
732	        return None, "title 必须是字符串"
733	    title = title.strip()
734	    if not title:
735	        return None, "title 不能为空（或全为空白字符）"
736	
737	    description = obj.get("description", "")
738	    if not isinstance(description, str):
739	        return None, "description 必须是字符串"
740	
741	    if "questions" not in obj:
742	        return None, "缺少字段 questions"
743	    raw_questions = obj["questions"]
744	    if not isinstance(raw_questions, list):
745	        return None, "questions 必须是数组"
746	    if len(raw_questions) == 0:
747	        return None, "questions 至少需要一道题"
748	
749	    questions = []
750	    for index, raw_question in enumerate(raw_questions, start=1):
751	        location = f"第 {index} 题"
752	        if not isinstance(raw_question, dict):
753	            return None, f"{location}（questions[{index - 1}]）必须是对象"
754	
755	        if "type" not in raw_question:
756	            return None, f"{location}：缺少字段 type"
757	        question_type = raw_question["type"]
758	        if not isinstance(question_type, str):
759	            return None, f"{location}：type 必须是字符串"
760	        if question_type not in QUESTION_TYPES:
761	            shown = json.dumps(question_type, ensure_ascii=False)
762	            return None, f"{location}：不支持的题型 {shown}（仅支持 text 或 single_choice）"
763	
764	        if "title" not in raw_question:
765	            return None, f"{location}：缺少字段 title"
766	        question_title = raw_question["title"]
767	        if not isinstance(question_title, str):
768	            return None, f"{location}：title 必须是字符串"
769	        question_title = question_title.strip()
770	        if not question_title:
771	            return None, f"{location}：题目标题不能为空（或全为空白字符）"
772	
773	        required = raw_question.get("required", False)
774	        if not isinstance(required, bool):
775	            return None, f"{location}：required 必须是布尔值"
776	
777	        raw_options = raw_question.get("options", [])
778	        if not isinstance(raw_options, list):
779	            return None, f"{location}：options 必须是数组"
780	
781	        options = []
782	        if question_type == "text":
783	            if len(raw_options) > 0:
784	                return None, f"{location}：文本题不能包含选项（options 必须省略或为空数组）"
785	        else:
786	            if len(raw_options) < 2:
787	                return None, f"{location}：单选题至少需要两个选项"
788	            seen = set()
789	            for option_index, raw_option in enumerate(raw_options, start=1):
790	                if not isinstance(raw_option, str):
791	                    return None, f"{location}：第 {option_index} 个选项必须是字符串"
792	                option = raw_option.strip()
793	                if not option:
794	                    return None, f"{location}：第 {option_index} 个选项不能为空（或全为空白字符）"
795	                if option in seen:
796	                    shown = json.dumps(option, ensure_ascii=False)
797	                    return None, f"{location}：选项 {shown} 重复（同一题内选项不得重复）"
798	                seen.add(option)
799	                options.append(option)
800	
801	        questions.append({
802	            "type": question_type,
803	            "title": question_title,
804	            "required": required,
805	            "options": options,
806	        })
807	
808	    return {
809	        "title": title,
810	        "description": description,
811	        "questions": questions,
812	    }, None
