815	def main():
816	    parser = argparse.ArgumentParser(description="OpenSurvey - 问卷调查与反馈管理")
817	    commands = parser.add_subparsers(dest="command", required=True)
818	    serve = commands.add_parser("serve", help="Start the HTTP service")
819	    serve.add_argument("--host", default="127.0.0.1", help="Address to bind (default: 127.0.0.1)")
